                // col_idx = 4 - (j % 5);
                // Actually, the RTL formula is: index = (4 - i_loop) * 5 + (4 - j_loop)
                // So:
                // i_loop = 4 - (j / 5);
                // j_loop = 4 - (j % 5);
                // expected[j] = ~(in_arr[i_loop] ^ in_arr[j_loop]);

