                // indices:
                // index = (4 - r) * 5 + (4 - c_val)
            end

            // Re-evaluating expected cleanly:
            begin
                integer r, c_val;
                for (r = 0; r < 5; r = r + 1) begin
                    for (c_val = 0; c_val < 5; c_val = c_val + 1) begin
                        integer idx;
                        idx = (4 - r) * 5 + (4 - c_val);
                        expected[idx] = ~(in_arr[r] ^ in_arr[c_val]);
                    end
                end
            end

            // 4-State Output Equality Check using !==
            if (out !== expected) begin
                $display("Mismatch at inputs a=%b b=%b c=%b d=%b e=%b: expected %b, got %b",
                         a, b, c, d, e, expected, out);
                errors = errors + 1;
            end
        end

        // Final result reporting
        if (errors === 0) begin
            $display("*** TEST RESULT: PASS ***");
        end else begin
            $display("*** TEST RESULT: FAIL ***");
        end
        $finish;
    end

endmodule
